package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static org.jlinalg.cli.NextflowFiles.*;
import static org.jlinalg.cli.IqRequest.require;

/** Exact original bytes and producer; complete populations and numerical replay without original paths. */
final class IqBundle {
    static final String PROFILE="native-iq-2.3.0-fast-maxlfq-v1";
    static final String ACTION="Required action: read WARNINGS.md, OUTPUT-AUDIT.json, ROWS.jsonl, SAMPLES.jsonl and PROTEINS.jsonl. Require COMPLETED.json and successful iq-tools --verify using the exact producing JAR before downstream use. SKIP3 means the qualified executable prerequisite is unavailable; supply the named permitted source-built JAR or retain the skip. FAIL2 means no complete result for invalid/changing input, capacity, cancellation, arithmetic, convergence or finalization failure. Preserve attempts and correct the cause using NEW paths. Never refresh historical seals. Hashes establish integrity, not biological suitability. Cell Ranger remains excluded.";
    private IqBundle() { }
    static final class Unavailable extends IOException { private static final long serialVersionUID=1L;Unavailable(String message){super(message);} }
    static Pin producer()throws IOException {
        try {Path jar=Path.of(IqBundle.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toAbsolutePath().normalize();if(!jar.getFileName().toString().endsWith(".jar"))throw new Unavailable("A complete source-built executable JAR is required for exact-producer iq capture; class-directory execution is not a qualified capture runtime");return pin(jar,1000000000L,()->{});}
        catch(java.net.URISyntaxException|NullPointerException error){throw new Unavailable("Cannot locate the exact producing iq JAR; build the complete executable and skip dependent analysis until available");}
    }
    static Runnable bounded(IqRequest.Spec spec,Runnable cancellation){long started=System.nanoTime();return()->{cancellation.run();if(Thread.currentThread().isInterrupted()||(System.nanoTime()-started)/1000000>spec.capacity().wallMillis())throw new IllegalStateException("iq cooperative wall limit/cancellation; no result admitted");};}
    static Path capture(Path supplied,IqRequest.Spec spec,Runnable cancellation)throws IOException {
        Path root=supplied.toAbsolutePath().normalize();require(root.isAbsolute()&&root.getParent()!=null&&supplied.toAbsolutePath().equals(root),"Require a NEW canonical iq result path");directory(root.getParent());require(!Files.exists(root,LinkOption.NOFOLLOW_LINKS),"iq result path already exists; use a NEW path");
        Runnable check=bounded(spec,cancellation);Path original=Path.of(spec.file());Pin source=pin(original,spec.capacity().inputBytes(),check),producer=producer();boolean created=false;String stage="CREATE_NEW_CAPTURE";
        try {
            Files.createDirectory(root);created=true;writeJson(root.resolve("INCOMPLETE.json"),Map.of("stage",stage,"analysis_admitted",false));Files.createDirectory(root.resolve("inputs"));Files.createDirectory(root.resolve("outputs"));
            writeJson(root.resolve("request.json"),spec.value());Files.writeString(root.resolve("WARNINGS.md"),warnings(),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);
            stage="COPY_COMPLETE_ORIGINAL_INPUT";Files.copy(original,root.resolve("inputs/ions.table"));require(source.equals(pin(root.resolve("inputs/ions.table"),spec.capacity().inputBytes(),check))&&source.equals(pin(original,spec.capacity().inputBytes(),check)),"Original iq input changed during complete capture");writeJson(root.resolve("source-inputs.json"),Map.of("original",spec.file(),"pin",source,"complete_original_bytes",true));
            stage="NATIVE_AGGREGATION";writeJson(root.resolve("OUTPUT-AUDIT.json"),IqCompute.run(root,spec,false,check));require(producer.equals(producer())&&source.equals(pin(original,spec.capacity().inputBytes(),check)),"Producing JAR or original iq input changed");
            stage="FINALIZE_AND_RECOMPUTE";var files=files(root,spec,check);files.remove("INCOMPLETE.json");writeJson(root.resolve("manifest.json"),Map.of("schema_version",1,"profile",PROFILE,"producer",producer,"files",files,"analysis_admitted",true,"whole_paper_reproduced",false));writeJson(root.resolve("COMPLETED.json"),Map.of("schema_version",1,"status","COMPLETE_NATIVE_IQ_CAPTURE","manifest",pin(root.resolve("manifest.json"),1048576,check),"analysis_admitted",true));verify(root,true,check);require(source.equals(pin(original,spec.capacity().inputBytes(),check))&&producer.equals(producer()),"Original iq input/producer changed before final admission");Files.delete(root.resolve("INCOMPLETE.json"));return root;
        }catch(IOException|RuntimeException|Error error){if(created)failure(root,stage,error);throw error;}
    }
    static void verify(Path supplied,boolean precommit,Runnable cancellation)throws IOException {
        Path root=supplied.toAbsolutePath().normalize();directory(root);require(!Files.exists(root.resolve("FAILURE.json"),LinkOption.NOFOLLOW_LINKS)&&Files.exists(root.resolve("INCOMPLETE.json"),LinkOption.NOFOLLOW_LINKS)==precommit,"Failed/incomplete iq attempt is not admitted");
        var done=object(json(root.resolve("COMPLETED.json"),1048576));keys(done,"schema_version","status","manifest","analysis_admitted");integer(done.get("schema_version"),1,1);require("COMPLETE_NATIVE_IQ_CAPTURE".equals(done.get("status"))&&Boolean.TRUE.equals(done.get("analysis_admitted")),"Missing complete iq admission");
        Pin manifest=pin(root.resolve("manifest.json"),1048576,cancellation);require(manifest.equals(fingerprint(done.get("manifest"),1048576)),"Saved iq manifest changed");var saved=object(json(root.resolve("manifest.json"),1048576));keys(saved,"schema_version","profile","producer","files","analysis_admitted","whole_paper_reproduced");integer(saved.get("schema_version"),1,1);require(PROFILE.equals(saved.get("profile"))&&Boolean.TRUE.equals(saved.get("analysis_admitted"))&&Boolean.FALSE.equals(saved.get("whole_paper_reproduced")),"Different/expanded iq contract");require(producer().equals(fingerprint(saved.get("producer"),1000000000L)),"Restore exact producing iq JAR; do not reseal a different producer");
        var spec=IqRequest.read(root.resolve("request.json"),false);Runnable check=bounded(spec,cancellation);inventory(root,spec,saved.get("files"),precommit,check);var declaration=object(json(root.resolve("source-inputs.json"),1048576));keys(declaration,"original","pin","complete_original_bytes");require(spec.file().equals(declaration.get("original"))&&Boolean.TRUE.equals(declaration.get("complete_original_bytes")),"Different original iq input declaration");require(pin(root.resolve("inputs/ions.table"),spec.capacity().inputBytes(),check).equals(fingerprint(declaration.get("pin"),spec.capacity().inputBytes())),"Captured original iq input bytes changed");
        require(Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warnings()),"Saved iq warnings/actions changed");require(NextflowJson.json(IqCompute.run(root,spec,true,check)).equals(NextflowJson.json(json(root.resolve("OUTPUT-AUDIT.json"),1048576))),"Saved iq population/numerical audit differs");inventory(root,spec,saved.get("files"),precommit,check);require(manifest.equals(pin(root.resolve("manifest.json"),1048576,check))&&producer().equals(fingerprint(saved.get("producer"),1000000000L)),"Manifest/producer changed during saved iq verification");
    }
    static Map<String,Object> files(Path root,IqRequest.Spec spec,Runnable check)throws IOException {
        var result=new TreeMap<String,Object>();long total=Math.addExact(Math.addExact(spec.capacity().inputBytes(),spec.capacity().outputBytes()),16777216L),generated=0;
        for(var entry:tree(root,32,total,Math.max(spec.capacity().inputBytes(),spec.capacity().outputBytes())+16777216L,check).entrySet()){
            require(entry.getValue().kind().equals("file"),"Links are not iq capture members");Pin value=entry.getValue().pin();if(!entry.getKey().equals("inputs/ions.table")){generated=Math.addExact(generated,value.bytes());require(generated<=spec.capacity().outputBytes()+16777216L,"Complete iq generated bytes exceed output_bytes plus16MiB metadata reserve");}result.put(entry.getKey(),Map.of("bytes",value.bytes(),"sha256",value.sha256()));
        }return result;
    }
    static void inventory(Path root,IqRequest.Spec spec,Object declared,boolean precommit,Runnable check)throws IOException {
        var directories=new HashSet<>(Set.of("","inputs","outputs"));try(var stream=Files.walk(root)){var iterator=stream.iterator();while(iterator.hasNext()){check.run();Path p=iterator.next();if(Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS))require(directories.remove(root.relativize(p).toString().replace('\\','/')),"Extra iq capture directory");}}require(directories.isEmpty(),"Missing iq capture directory");
        var actual=files(root,spec,check);var names=new HashSet<>(Set.of("request.json","WARNINGS.md","inputs/ions.table","source-inputs.json","ROWS.jsonl","PROTEINS.jsonl","SAMPLES.jsonl","outputs/proteins.tsv","OUTPUT-AUDIT.json","manifest.json","COMPLETED.json"));if(precommit)names.add("INCOMPLETE.json");require(actual.keySet().equals(names),"Missing/extra file in complete iq capture namespace");actual.remove("manifest.json");actual.remove("COMPLETED.json");actual.remove("INCOMPLETE.json");require(NextflowJson.json(actual).equals(NextflowJson.json(declared)),"Complete saved iq byte population changed");
    }
    static void failure(Path root,String stage,Throwable error){try{Files.deleteIfExists(root.resolve("COMPLETED.json"));if(!Files.exists(root.resolve("FAILURE.json"),LinkOption.NOFOLLOW_LINKS))writeJson(root.resolve("FAILURE.json"),Map.of("status","FAIL2_NO_COMPLETE_IQ_RESULT","stage",stage,"error",error.toString(),"required_action",ACTION,"analysis_admitted",false));}catch(IOException suppressed){error.addSuppressed(suppressed);}}
    static String warnings(){return "IQ WARNINGS AND REQUIRED ACTION\n\nNative Java iq2.3.0 fast_MaxLFQ semantics. Supply already normalized LOG2 ion/precursor intensities and declare the preparation. No raw-intensity conversion, FDR selection, normalization, missing-value imputation or filtering is inferred. Zero and negative log2 values are valid; literal input NA/Inf fails instead of being silently dropped. No upstream R executable is run and no dependency is downloaded/installed during analysis.\n\nDuplicate protein/ion/sample cells sum in LINEAR space as iq2.3.0, then return to log2. Do not substitute the older iq1.9.12 last-row overwrite behavior. Nonfinite source duplicate sums fail. Complete first-observed protein/sample/ion identities, every input row and unused cell remain captured. Pairwise medians use common ions with one edge per eligible sample pair; edges are not weighted by overlap counts. Connected components are independently centered to their observed-cell mean; isolated samples use the median. Single-ion components follow the source shortcut. Missing protein/sample values remain NA, not zero. Source annotations and zero-based component labels include missing-sample component positions. The protein TSV is LONG format to preserve literal sample labels without reserved-header collisions.\n\nThe bit-graph conjugate-gradient solver uses source squared-relative threshold1e-20, at most10*(samples+1) iterations and any lower declared limit. Nonconvergence/breakdown fails; a best iterate is not admitted. The final residual is independently recomputed. Complete populations, numeric scans, multiply-add work, numeric memory estimates, bytes and cooperative time/cancellation limits are bounded; no JVM heap guarantee is made. Retained input row/identifier memory is reserved before numerical work. Table records are limited to1Mi characters and1024 columns; decoded bytes are counted. Provision JVM heap for the full populations and use a NEW attempt if limits are inadequate.\n\nThis is the iq aggregation role in P168, not the Proteograph cloud workflow, PepCal extraction/drift smoothing, DIA-NN search or limma plate correction. The paper does not report an iq edition or complete aggregation inputs; no author version, normalization or full study reproduction is inferred. IQ's streaming formats, weighted estimators and other package functions remain separate.\n\nSaved verification checks the complete byte/file/directory namespace and exact producer, then recomputes all rows, identities, duplicates, components, estimates and audits from captured original bytes. It never reads original host input paths. Keep the exact producing JAR and private evidence.\n\n"+ACTION+"\n";}
}
